// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(address caller) public {

        bool ok;
        bool pausedValue;

        vm.prank(caller);
        try c.paused() returns (bool v) {
            ok = true;
            pausedValue = v;
        } catch {
            ok = false;
            pausedValue = false;
        }

        assertTrue(ok && pausedValue == false);
    }
}
